\leader{263H}{Corollary} If $k\in\Bbb N$ is odd,

\Centerline{$\int_{-\infty}^{\infty}x^ke^{-x^2/2}dx=0$;}

\noindent if $k=2l\in\Bbb N$ is even, then

\Centerline{$\int_{-\infty}^{\infty}x^ke^{-x^2/2}dx
=\Bover{(2l)!}{2^ll!}\sqrt{2\pi}$.}

